const VALID_CHARS = /^[A-Za-z0-9_.:\/-]+$/;

export function isValidName(name) {
  return VALID_CHARS.test(name);
}

export function isValidUnsignedInt(value, min = 0) {
  if (!/^\d+$/.test(value)) return false;
  if (value !== '0' && value[0] === '0') return false; // no leading zero
  return parseInt(value, 10) >= min;
}

export class Parser {
  constructor() {
    this.policies = new Map(); // name -> { type, ...config }
    this.routes = []; // [ { prefix, policyNames }, ... ]
    this.routePrefixes = new Set();
    this.events = []; // [ { tick, key }, ... ]
    this.firstEventLine = null;
    this.lastTick = null;
  }

  parse(input) {
    const lines = input.split('\n');
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) continue;

      const lineNum = i + 1;
      const parts = line.split(/\s+/);

      try {
        const directive = parts[0];

        if (directive === 'bucket') {
          this.parseBucket(parts, lineNum);
        } else if (directive === 'window') {
          this.parseWindow(parts, lineNum);
        } else if (directive === 'route') {
          this.parseRoute(parts, lineNum);
        } else if (directive === 'event') {
          this.parseEvent(parts, lineNum);
        } else {
          return { error: `unknown directive ${directive}`, line: lineNum };
        }
      } catch (err) {
        return { error: err.message, line: lineNum };
      }
    }

    return { error: null, line: null };
  }

  parseBucket(parts, lineNum) {
    if (parts.length !== 5) {
      throw new Error('expected bucket <name> <capacity> <refill> <per>');
    }

    const [, name, capacity, refill, per] = parts;

    if (!isValidName(name)) {
      throw new Error(`invalid policy name ${name}`);
    }

    if (!isValidUnsignedInt(capacity, 1)) {
      throw new Error('capacity must be an integer of at least 1');
    }

    if (!isValidUnsignedInt(refill, 0)) {
      throw new Error('refill must be an integer of at least 0');
    }

    if (!isValidUnsignedInt(per, 1)) {
      throw new Error('per must be an integer of at least 1');
    }

    if (this.policies.has(name)) {
      throw new Error(`policy ${name} is declared twice`);
    }

    this.policies.set(name, {
      type: 'bucket',
      capacity: parseInt(capacity, 10),
      refill: parseInt(refill, 10),
      per: parseInt(per, 10)
    });
  }

  parseWindow(parts, lineNum) {
    if (parts.length !== 5) {
      throw new Error('expected window <name> <limit> <span>');
    }

    const [, name, limit, span] = parts;

    if (!isValidName(name)) {
      throw new Error(`invalid policy name ${name}`);
    }

    if (!isValidUnsignedInt(limit, 0)) {
      throw new Error('limit must be an integer of at least 0');
    }

    if (!isValidUnsignedInt(span, 1)) {
      throw new Error('span must be an integer of at least 1');
    }

    if (this.policies.has(name)) {
      throw new Error(`policy ${name} is declared twice`);
    }

    this.policies.set(name, {
      type: 'window',
      limit: parseInt(limit, 10),
      span: parseInt(span, 10)
    });
  }

  parseRoute(parts, lineNum) {
    if (parts.length < 2) {
      throw new Error('expected route <prefix> <policy>...');
    }

    const prefix = parts[1];
    const policyNames = parts.slice(2);

    if (!isValidName(prefix)) {
      throw new Error(`invalid route prefix ${prefix}`);
    }

    if (policyNames.length === 0) {
      throw new Error('expected route <prefix> <policy>...');
    }

    if (this.routePrefixes.has(prefix)) {
      throw new Error(`prefix ${prefix} is routed twice`);
    }

    // Validate that all policies exist
    for (const policyName of policyNames) {
      if (!this.policies.has(policyName)) {
        throw new Error(`unknown policy ${policyName}`);
      }
    }

    this.routePrefixes.add(prefix);
    this.routes.push({ prefix, policyNames });
  }

  parseEvent(parts, lineNum) {
    if (this.firstEventLine === null) {
      this.firstEventLine = lineNum;
    }

    if (parts.length !== 3) {
      throw new Error('expected event <tick> <key>');
    }

    const [, tick, key] = parts;

    if (!isValidUnsignedInt(tick, 0)) {
      throw new Error('tick must be an integer of at least 0');
    }

    if (!isValidName(key)) {
      throw new Error(`invalid key ${key}`);
    }

    const tickNum = parseInt(tick, 10);

    if (this.lastTick !== null && tickNum < this.lastTick) {
      throw new Error(`tick ${tickNum} is before tick ${this.lastTick}`);
    }

    this.lastTick = tickNum;
    this.events.push({ tick: tickNum, key });
  }

  ensureDeclarationsBeforeEvents(lineNum) {
    if (this.firstEventLine !== null && lineNum > this.firstEventLine) {
      throw new Error('declarations must come before the first event');
    }
  }
}
"}

