{"file_path":"src/policies.js","content":"/**
 * Implementations of token bucket and sliding window rate limiters.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
    this.states = new Map(); // key -> { tokens, lastTick }
  }

  advance(key, tick) {
    if (!this.states.has(key)) {
      // First time this key reaches this policy - start full
      this.states.set(key, { tokens: this.capacity, lastTick: tick });
      return;
    }

    const state = this.states.get(key);
    const elapsed = tick - state.lastTick;

    if (elapsed > 0) {
      // Add tokens: refill * elapsed / per
      // Using fractions to avoid rounding issues
      const tokensToAdd = (this.refill * elapsed) / this.per;
      state.tokens = Math.min(state.tokens + tokensToAdd, this.capacity);
      state.lastTick = tick;
    }
  }

  allow(key) {
    const state = this.states.get(key);
    return state && state.tokens >= 1;
  }

  record(key) {
    const state = this.states.get(key);
    if (state) {
      state.tokens -= 1;
    }
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit;
    this.span = span;
    this.states = new Map(); // key -> ticks[]
  }

  advance(key, tick) {
    if (!this.states.has(key)) {
      this.states.set(key, []);
    }

    const ticks = this.states.get(key);
    // Remove ticks older than tick - span
    const cutoff = tick - this.span;
    while (ticks.length > 0 && ticks[0] <= cutoff) {
      ticks.shift();
    }
  }

  allow(key) {
    const ticks = this.states.get(key);
    return ticks && ticks.length < this.limit;
  }

  record(key, tick) {
    const ticks = this.states.get(key);
    if (ticks) {
      ticks.push(tick);
    }
  }
}

export function createPolicy(config) {
  if (config.type === 'bucket') {
    return new TokenBucket(config.capacity, config.refill, config.per);
  } else if (config.type === 'window') {
    return new SlidingWindow(config.limit, config.span);
  }
  throw new Error(`Unknown policy type: ${config.type}`);
}
"}

