export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
    this.states = new Map(); // key -> { tokens, lastTick }
  }

  advance(key, tick) {
    if (!this.states.has(key)) {
      // First time this key reaches this policy - start full
      this.states.set(key, { tokens: this.capacity, lastTick: tick });
      return;
    }

    const state = this.states.get(key);
    const elapsed = tick - state.lastTick;

    if (elapsed > 0) {
      // Add tokens: refill * elapsed / per
      // Using fractions to avoid rounding issues
      const tokensToAdd = (this.refill * elapsed) / this.per;
      state.tokens = Math.min(state.tokens + tokensToAdd, this.capacity);
      state.lastTick = tick;
    }
  }

  allow(key) {
    const state = this.states.get(key);
    return state && state.tokens >= 1;
  }

  record(key) {
    const state = this.states.get(key);
    if (state) {
      state.tokens -= 1;
    }
  }
