 * Simulator for processing events against rate limiting policies.
 */

import { createPolicy } from './policies.js';

export class Simulator {
  constructor(policies, routes) {
    this.policyInstances = new Map();

    // Create policy instances
    for (const [name, config] of policies) {
      this.policyInstances.set(name, createPolicy(config));
    }

    // Sort routes by prefix length (longest first) for matching
    this.routes = routes.sort((a, b) => b.prefix.length - a.prefix.length);
  }

  findRoute(key) {
    for (const route of this.routes) {
      if (key.startsWith(route.prefix)) {
        return route;
      }
    }
    return null;
  }

  processEvent(tick, key) {
    const route = this.findRoute(key);

    if (!route) {
      // No route matches - always allow
      return { allowed: true, denyPolicy: null };
    }

    // Advance all policies to this tick
    for (const policyName of route.policyNames) {
      const policy = this.policyInstances.get(policyName);
      policy.advance(key, tick);
    }

    // Check if all policies allow
    for (const policyName of route.policyNames) {
      const policy = this.policyInstances.get(policyName);
      if (!policy.allow(key)) {
        return { allowed: false, denyPolicy: policyName };
      }
    }

    // All policies allowed - record the event
    for (const policyName of route.policyNames) {
      const policy = this.policyInstances.get(policyName);
      policy.record(key, tick);
    }

    return { allowed: true, denyPolicy: null };
  }
}
"}

