{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { Parser, isValidName, isValidUnsignedInt } from './parser.js';
import { Simulator } from './simulator.js';
import * as readline from 'readline';

function exit(code, message = '') {
  if (message) {
    process.stderr.write(message);
  }
  process.exit(code);
}

async function readInput() {
  const lines = [];
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
  });

  for await (const line of rl) {
    lines.push(line);
  }

  return lines.join('\n');
}

function replay(simulator, events) {
  const output = [];
  for (const event of events) {
    const result = simulator.processEvent(event.tick, event.key);
    if (result.allowed) {
      output.push(`${event.tick} ${event.key} allow`);
    } else {
      output.push(`${event.tick} ${event.key} deny ${result.denyPolicy}`);
    }
  }
  return output.join('\n') + (output.length > 0 ? '\n' : '');
}

function summary(simulator, events) {
  const keyStats = new Map();
  let totalAllowed = 0;
  let totalDenied = 0;

  for (const event of events) {
    const result = simulator.processEvent(event.tick, event.key);

    if (!keyStats.has(event.key)) {
      keyStats.set(event.key, { allowed: 0, denied: 0 });
    }

    const stats = keyStats.get(event.key);
    if (result.allowed) {
      stats.allowed++;
      totalAllowed++;
    } else {
      stats.denied++;
      totalDenied++;
    }
  }

  const output = [];

  // Sort keys in ascending order
  const sortedKeys = Array.from(keyStats.keys()).sort();
  for (const key of sortedKeys) {
    const stats = keyStats.get(key);
    output.push(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
  }

  output.push(`total allowed=${totalAllowed} denied=${totalDenied}`);
  return output.join('\n') + '\n';
}

async function main() {
  // Check arguments
  if (process.argv.length !== 3) {
    exit(2, 'error: usage: cli.js replay|summary\n');
  }

  const mode = process.argv[2];
  if (mode !== 'replay' && mode !== 'summary') {
    exit(2, 'error: usage: cli.js replay|summary\n');
  }

  // Read input
  const input = await readInput();

  // Parse input
  const parser = new Parser();

  const lines = input.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) continue;

    const lineNum = i + 1;
    const parts = line.split(/\s+/);

    try {
      const directive = parts[0];

      if (directive === 'bucket') {
        // Check that declarations come before first event
        if (parser.firstEventLine !== null) {
          exit(2, `error: line ${lineNum}: declarations must come before the first event\n`);
        }

        if (parts.length !== 5) {
          exit(2, `error: line ${lineNum}: expected bucket <name> <capacity> <refill> <per>\n`);
        }

        const [, name, capacity, refill, per] = parts;

        if (!isValidName(name)) {
          exit(2, `error: line ${lineNum}: invalid policy name ${name}\n`);
        }

        if (!isValidUnsignedInt(capacity, 1)) {
          exit(2, `error: line ${lineNum}: capacity must be an integer of at least 1\n`);
        }

        if (!isValidUnsignedInt(refill, 0)) {
          exit(2, `error: line ${lineNum}: refill must be an integer of at least 0\n`);
        }

        if (!isValidUnsignedInt(per, 1)) {
          exit(2, `error: line ${lineNum}: per must be an integer of at least 1\n`);
        }

        if (parser.policies.has(name)) {
          exit(2, `error: line ${lineNum}: policy ${name} is declared twice\n`);
        }

        parser.policies.set(name, {
          type: 'bucket',
          capacity: parseInt(capacity, 10),
          refill: parseInt(refill, 10),
          per: parseInt(per, 10)
        });
      } else if (directive === 'window') {
        // Check that declarations come before first event
        if (parser.firstEventLine !== null) {
          exit(2, `error: line ${lineNum}: declarations must come before the first event\n`);
        }

        if (parts.length !== 5) {
          exit(2, `error: line ${lineNum}: expected window <name> <limit> <span>\n`);
        }

        const [, name, limit, span] = parts;

        if (!isValidName(name)) {
          exit(2, `error: line ${lineNum}: invalid policy name ${name}\n`);
        }

        if (!isValidUnsignedInt(limit, 0)) {
          exit(2, `error: line ${lineNum}: limit must be an integer of at least 0\n`);
        }

        if (!isValidUnsignedInt(span, 1)) {
          exit(2, `error: line ${lineNum}: span must be an integer of at least 1\n`);
        }

        if (parser.policies.has(name)) {
          exit(2, `error: line ${lineNum}: policy ${name} is declared twice\n`);
        }

        parser.policies.set(name, {
          type: 'window',
          limit: parseInt(limit, 10),
          span: parseInt(span, 10)
        });
      } else if (directive === 'route') {
        // Check that declarations come before first event
        if (parser.firstEventLine !== null) {
          exit(2, `error: line ${lineNum}: declarations must come before the first event\n`);
        }

        if (parts.length < 3) {
          exit(2, `error: line ${lineNum}: expected route <prefix> <policy>...\n`);
        }

        const prefix = parts[1];
        const policyNames = parts.slice(2);

        if (!isValidName(prefix)) {
          exit(2, `error: line ${lineNum}: invalid route prefix ${prefix}\n`);
        }

        if (policyNames.length === 0) {
          exit(2, `error: line ${lineNum}: expected route <prefix> <policy>...\n`);
        }

        if (parser.routePrefixes.has(prefix)) {
          exit(2, `error: line ${lineNum}: prefix ${prefix} is routed twice\n`);
        }

        // Validate that all policies exist
        for (const policyName of policyNames) {
          if (!parser.policies.has(policyName)) {
            exit(2, `error: line ${lineNum}: unknown policy ${policyName}\n`);
          }
        }

        parser.routePrefixes.add(prefix);
        parser.routes.push({ prefix, policyNames });
      } else if (directive === 'event') {
        if (parser.firstEventLine === null) {
          parser.firstEventLine = lineNum;
        }

        if (parts.length !== 3) {
          exit(2, `error: line ${lineNum}: expected event <tick> <key>\n`);
        }

        const [, tick, key] = parts;

        if (!isValidUnsignedInt(tick, 0)) {
          exit(2, `error: line ${lineNum}: tick must be an integer of at least 0\n`);
        }

        if (!isValidName(key)) {
          exit(2, `error: line ${lineNum}: invalid key ${key}\n`);
        }

        const tickNum = parseInt(tick, 10);

        if (parser.lastTick !== null && tickNum < parser.lastTick) {
          exit(2, `error: line ${lineNum}: tick ${tickNum} is before tick ${parser.lastTick}\n`);
        }

        parser.lastTick = tickNum;
        parser.events.push({ tick: tickNum, key });
      } else {
        exit(2, `error: line ${lineNum}: unknown directive ${directive}\n`);
      }
    } catch (err) {
      exit(2, `error: line ${lineNum}: ${err.message}\n`);
    }
  }

  // Create simulator and process events
  const simulator = new Simulator(parser.policies, parser.routes);

  let output;
  if (mode === 'replay') {
    output = replay(simulator, parser.events);
  } else {
    output = summary(simulator, parser.events);
  }

  process.stdout.write(output);
  process.exit(0);
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});
"}

