{"file_path":"src/policies.js","content":"/**
 * Implementations of token bucket and sliding window rate limiters.
 *
 * All arithmetic is exact: token counts are held as integers scaled by the
 * bucket's period, so a partial period never rounds away, and ticks are
 * BigInt so arbitrarily large values stay exact.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = BigInt(capacity);
    this.refill = BigInt(refill);
    this.per = BigInt(per);
    // tokens are stored scaled by `per`: scaled = tokens * per
    this.capacityScaled = this.capacity * this.per;
    this.states = new Map(); // key -> { scaled, lastTick }
  }

  advance(key, tick) {
    const t = BigInt(tick);
    if (!this.states.has(key)) {
      // First time this key reaches this policy - start full
      this.states.set(key, { scaled: this.capacityScaled, lastTick: t });
      return;
    }

    const state = this.states.get(key);
    const elapsed = t - state.lastTick;

    if (elapsed > 0n) {
      // exact: refill * elapsed / per tokens, i.e. refill * elapsed scaled units
      let next = state.scaled + this.refill * elapsed;
      if (next > this.capacityScaled) next = this.capacityScaled;
      state.scaled = next;
      state.lastTick = t;
    }
  }

  allow(key) {
    const state = this.states.get(key);
    return !!state && state.scaled >= this.per;
  }

  record(key) {
    const state = this.states.get(key);
    if (state) {
      state.scaled -= this.per;
    }
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = BigInt(limit);
    this.span = BigInt(span);
    this.states = new Map(); // key -> { ticks: [], head: number }
  }

  advance(key, tick) {
    const t = BigInt(tick);
    if (!this.states.has(key)) {
      this.states.set(key, { ticks: [], head: 0 });
    }

    const state = this.states.get(key);
    // Forget every remembered tick at or before tick - span
    const cutoff = t - this.span;
    while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) {
      state.head++;
    }
    if (state.head > 64 && state.head * 2 >= state.ticks.length) {
      state.ticks = state.ticks.slice(state.head);
      state.head = 0;
    }
  }

  allow(key) {
    const state = this.states.get(key);
    if (!state) return false;
    return BigInt(state.ticks.length - state.head) < this.limit;
  }

  record(key, tick) {
    const state = this.states.get(key);
    if (state) {
      state.ticks.push(BigInt(tick));
    }
  }
}

export function createPolicy(config) {
  if (config.type === 'bucket') {
    return new TokenBucket(config.capacity, config.refill, config.per);
  } else if (config.type === 'window') {
    return new SlidingWindow(config.limit, config.span);
  }
  throw new Error(`Unknown policy type: ${config.type}`);
}
"}

