                    st[key] = [t for t in lst if t > tick - span]
            for n in route:
                cfg = policies[n]; st = state[n]
                ok = (st[key][0] >= 1) if cfg[0]=='bucket' else (len(st[key]) < cfg[1])
                if not ok:
                    denier = n; break
            if denier is None:
                for n in route:
                    if policies[n][0]=='bucket': state[n][key][0] -= 1
                    else: state[n][key].append(tick)
        if denier is None:
            out.append(f"{tick} {key} allow"); stats.setdefault(key,[0,0])[0]+=1; ta+=1
        else:
