    if mode == 'replay':
        return "".join(l+"\n" for l in out)
    res = ""
    for k in sorted(stats):
        res += f"{k} allowed={stats[k][0]} denied={stats[k][1]}\n"
    res += f"total allowed={ta} denied={td}\n"
    return res
